import{_ as r,C as i,o as n,c as o,a2 as t,E as d}from"./chunks/framework.CDU0sSpB.js";const b=JSON.parse('{"title":"Delivery and progress","description":"What Hearth has delivered, what is still open, and the order in which the remaining work converges.","frontmatter":{"title":"Delivery and progress","description":"What Hearth has delivered, what is still open, and the order in which the remaining work converges.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/index.md","filePath":"en/delivery/index.md","lastUpdated":1793867008000}'),s={name:"en/delivery/index.md"};function l(c,e,h,p,u,m){const a=i("DocCardGrid");return n(),o("div",null,[e[0]||(e[0]=t('<h1 id="delivery-and-progress" tabindex="-1">Delivery and progress <a class="header-anchor" href="#delivery-and-progress" aria-label="Permalink to &quot;Delivery and progress&quot;">​</a></h1><p class="lead">This is not a roadmap that only describes the future. It starts from loops that already run, records which capabilities can be proven by code and tests, which boundaries remain open, and in what order the gaps will be closed.</p><h2 id="bottom-line" tabindex="-1">Bottom line <a class="header-anchor" href="#bottom-line" aria-label="Permalink to &quot;Bottom line&quot;">​</a></h2><p><strong>The phase-one MVP has passed its hard gate. Phases two through six have runnable code loops and automated coverage, but have not completed real-user, real-device, or long-running acceptance.</strong></p><p>Verification baseline on 2026-11-06: <code>npm test</code> passed 40 test files and 199 tests; <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run docs:build</code> passed. All 15 phase-one real tasks ran, and 13 passed acceptance.</p><h2 id="six-phases" tabindex="-1">Six phases <a class="header-anchor" href="#six-phases" aria-label="Permalink to &quot;Six phases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Status</th><th>Proven</th><th>Still open</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/mvp.html">1 · Minimum complete MVP</a></td><td><strong>Accepted</strong></td><td>15 real tasks, 13 passed; task, approval, artifact, recovery, and backup loops</td><td>T07 did not deliver a PR; T08&#39;s external comment awaits user approval</td></tr><tr><td><a href="/hearth-os/en/delivery/capabilities.html">2 · Everyday content work</a></td><td>Partial</td><td>Local files, knowledge bases, web sources; document extraction; drafts, approvals, local outbox, and receipts</td><td>No email or calendar accounts; no real sending</td></tr><tr><td><a href="/hearth-os/en/delivery/capabilities.html">3 · Desktop operation</a></td><td>Partial</td><td>Windows pairing, capability approval, observation, pause/takeover/hand-back, low-risk input, UIA actions</td><td>Sensitive-area masking, isolated desktop, high-risk compensation</td></tr><tr><td><a href="/hearth-os/en/delivery/capabilities.html">4 · Proactive service and mobile</a></td><td>Partial</td><td>Six trigger types, proactive inbox, accept/ignore/snooze/convert, attention budget</td><td>Mobile PWA, phone pairing, push, remote approval and takeover</td></tr><tr><td><a href="/hearth-os/en/delivery/capabilities.html">5 · Memory and evolution</a></td><td>Partial</td><td>Memory candidate/recall/correct/conflict/forget/export; method evaluate/promote/reject/rollback</td><td>Real long-term use and before/after production comparison</td></tr><tr><td><a href="/hearth-os/en/delivery/capabilities.html">6 · Multi-device and long-running</a></td><td>Partial</td><td>Incremental sync, peer auth, leases and epoch fencing, revocation, encrypted backup, health maintenance</td><td>Real two-device switch, lost-device drill, multi-week run</td></tr></tbody></table><h2 id="what-partial-means" tabindex="-1">What &quot;partial&quot; means <a class="header-anchor" href="#what-partial-means" aria-label="Permalink to &quot;What &quot;partial&quot; means&quot;">​</a></h2><p>&quot;Partial&quot; does not mean &quot;the page is done&quot;, and it does not mean &quot;the capability is delivered&quot;. It means only:</p><ol><li>The server, API, and projections have a runnable implementation.</li><li>Automated tests cover the main code paths and key boundaries.</li><li>Real accounts, real devices, real user tasks, or long-running evidence are still missing.</li></ol><p>Phases two through six therefore do not become &quot;accepted&quot; just because code merged. Each phase needs its own real task record, failure drill, and user verification.</p><h2 id="three-delivery-levels" tabindex="-1">Three delivery levels <a class="header-anchor" href="#three-delivery-levels" aria-label="Permalink to &quot;Three delivery levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th><th>Current state</th></tr></thead><tbody><tr><td><strong>Runnable</strong></td><td>The app starts locally and tasks can be created, executed, and viewed</td><td>Present</td></tr><tr><td><strong>Verified</strong></td><td>Tests, isolated runs, or real run records prove key paths</td><td>Phase one: yes; phases two–six: partial</td></tr><tr><td><strong>Accepted</strong></td><td>A real user, device, or external account completed the agreed tasks</td><td>Phase one: passed; phases two–six: not yet</td></tr></tbody></table><h2 id="why-the-route-was-rewritten" tabindex="-1">Why the route was rewritten <a class="header-anchor" href="#why-the-route-was-rewritten" aria-label="Permalink to &quot;Why the route was rewritten&quot;">​</a></h2><p>The old route described an implementation order that had not happened yet across six phases and 24 sub-stages. The project is now substantially built, and future-tense planning hides two questions: which capabilities already run, and which only have code without acceptance.</p><p>The new route uses three layers:</p><ul><li><strong>Delivery overview</strong>: phase status and the evidence boundary first.</li><li><strong>Capability status</strong>: implemented, verified, and deliberately empty by phase.</li><li><strong>Remaining roadmap</strong>: only unfinished workstreams, each with an exit condition.</li></ul><h2 id="continue-reading" tabindex="-1">Continue reading <a class="header-anchor" href="#continue-reading" aria-label="Permalink to &quot;Continue reading&quot;">​</a></h2>',18)),d(a,{columns:2,items:[{no:"01",title:"Phase-one MVP acceptance",text:"Results for 15 real tasks, T07/T08 boundaries, G1–G9 criteria, and evidence.",link:"/en/delivery/mvp"},{no:"02",title:"Phase 2–6 capabilities",text:"Implemented, verified, and deliberately open items by sub-stage.",link:"/en/delivery/capabilities"},{no:"03",title:"Remaining roadmap",text:"Seven workstreams, milestones, exit criteria, and explicit non-goals.",link:"/en/delivery/roadmap"},{no:"04",title:"Acceptance and evidence",text:"Test levels, evidence rules, reproduction commands, and the definition of done.",link:"/en/delivery/acceptance"}]}),e[1]||(e[1]=t('<h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>The priority is not to add more surface area, but to turn existing code loops into capabilities proven by real use:</p><ol><li>Connect real email and calendar accounts and complete 10–15 everyday content tasks.</li><li>Add desktop sensitive-area masking, isolated desktop, and high-risk actions; accept at least 5 desktop tasks.</li><li>Build the mobile entry and complete proactive interruption acceptance.</li><li>Run before/after comparisons with real memory and methods.</li><li>Drill two-device switching, lost-device handling, and backup restore.</li><li>Complete multi-week operation, upgrade rollback, and v1.0 acceptance.</li></ol><p>See <a href="/hearth-os/en/delivery/roadmap.html">Remaining roadmap</a> for order and exit criteria.</p>',4))])}const g=r(s,[["render",l]]);export{b as __pageData,g as default};
